use std::{fs::OpenOptions,io::Write};
use tauri::Manager;
fn safe_name(raw:&str)->String{let s:String=raw.chars().filter(|c|!c.is_control()).map(|c|if "/\\:*?\"<>|".contains(c){'_'}else{c}).scan(0,|n,c|{*n+=c.len_utf8();(*n<=170).then_some(c)}).collect();let stem=s.trim().trim_end_matches('.').strip_suffix(".pdf").unwrap_or(s.trim().trim_end_matches('.')).trim_matches('.').trim();if stem.is_empty(){"DF-Tuning-ajanlat".into()}else{format!("DF - {stem}")}}
#[tauri::command]
pub fn save_quote_pdf(app:tauri::AppHandle,filename:String,bytes:Vec<u8>)->Result<String,String>{let desktop=app.path().desktop_dir().map_err(|e|e.to_string())?;write_pdf(&desktop,&filename,&bytes)}
fn write_pdf(desktop:&std::path::Path,filename:&str,bytes:&[u8])->Result<String,String>{if bytes.len()>10_000_000||!bytes.starts_with(b"%PDF-"){return Err("Hibás vagy túl nagy PDF.".into());}let stem=safe_name(filename);for i in 0..1000{let name=if i==0{format!("{stem}.pdf")}else{format!("{stem} ({i}).pdf")};let path=desktop.join(name);match OpenOptions::new().write(true).create_new(true).open(&path){Ok(mut file)=>{if let Err(e)=file.write_all(bytes).and_then(|_|file.sync_all()){drop(file);let _=std::fs::remove_file(&path);return Err(e.to_string());}return Ok(path.to_string_lossy().into());},Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists=>continue,Err(e)=>return Err(e.to_string())}}Err("Nem található szabad exportfájlnév.".into())}
#[cfg(test)]mod tests{use super::*;#[test]fn safe_filename(){assert!(!safe_name("../../bad\\name:?.pdf").contains('/'));assert!(!safe_name("../bad\\name.pdf").contains('\\'));assert!(safe_name("Kovács Péter.pdf").contains("Kovács Péter"));}}

#[cfg(test)]mod export_tests{use super::*;#[test]fn export_never_overwrites(){let dir=std::env::temp_dir().join(format!("df-quote-test-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&dir).unwrap();let a=write_pdf(&dir,"Vevő.pdf",b"%PDF-test-a").unwrap();let b=write_pdf(&dir,"Vevő.pdf",b"%PDF-test-b").unwrap();assert_ne!(a,b);assert_eq!(std::fs::read(a).unwrap(),b"%PDF-test-a");assert!(write_pdf(&dir,"x.pdf",b"not a pdf").is_err());std::fs::remove_dir_all(dir).unwrap();}}
